class InMemoryQueryState:
    """Query state tracker backed by a plain dict instead of redis."""

    def __init__(self):
        self._states = {}

    def record(self, query_id, state):
        self._states[query_id] = state
        return state

    def current(self, query_id):
        return self._states.get(query_id)

