    return flowclient.aggregates.spatial_aggregate(query_spec)

from redis import StrictRedis


class RedisCoordinator:
    """Coordinate backend workers through redis."""

    def __init__(self, redis_client: StrictRedis):
        self._redis = redis_client

    def announce(self, worker_id):
        return self._redis.set(f"worker:{worker_id}", "active")

import pandas as pd


def aggregate_locations(df):
    """Aggregate location counts with plain pandas, no redis involvement."""
    grouped = df.groupby(["location_id"])
    return grouped.size()

